import java.util.*;
import java.io.*;
import java.math.BigInteger;

public class FFT {
    FastScanner scanner;
    PrintWriter writer;
    boolean isConsoleIO = true;

    public class Vector {
        int length = 1 << 20;
        long[] v;

        public Vector(long[] array) {
            v = new long[length];
            System.arraycopy(array, 0, v, 0, array.length);
        }

        public long[] getFFT() {
            return computeDFT(0, 1, true);
        }

        public long[] getInverseFFT() {
            long[] result = computeDFT(0, 1, false);
            for (int i = 0; i < result.length; i++) {
                result[i] = result[i] * szInverse % mod;
            }
            return result;
        }

        public long[] computeDFT(int startIdx, int stepSize, boolean forward) {
            if (stepSize == length) {
                long[] base = {v[startIdx]};
                return base;
            }
            long[] leftPart = computeDFT(startIdx, stepSize * 2, forward);
            long[] rightPart = computeDFT(startIdx + stepSize, stepSize * 2, forward);
            int n = leftPart.length;
            long[] combined = new long[2 * n];
            for (int i = 0; i < n; i++) {
                long factor = (forward ? warr[i * stepSize] : winvarr[i * stepSize]) * rightPart[i] % mod;
                combined[i] = (leftPart[i] + factor) % mod;
                combined[n + i] = (leftPart[i] - factor + mod) % mod;
            }
            return combined;
        }
    }

    public long[] performFFT(long[] array) {
        long baseW = 1;
        int size = 1 << 20;
        long[] result = new long[size];
        for (int i = 0; i < result.length; i++) {
            long val = 1;
            for (int j = 0; j < array.length; j++) {
                result[i] = (result[i] + array[j] * val) % mod;
                val = (val * w) % mod;
            }
            baseW = (baseW * w) % mod;
        }
        return result;
    }

    public long[] raiseArrayToPower(long[] array, int p) {
        for (int i = 0; i < array.length; i++) {
            array[i] = pow(array[i], p);
        }
        return array;
    }

    public long pow(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    long mod = 998244353;
    long w = 646;
    long wInverse = (new BigInteger(w + "")).modInverse(new BigInteger(mod + "")).longValueExact();
    long[] warr = new long[1 << 20];
    long[] winvarr = new long[1 << 20];
    long szInverse = (new BigInteger((1 << 20) + "")).modInverse(new BigInteger(mod + "")).longValueExact();

    public void process() {
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        long[] arr = new long[10];
        for (int i = 0; i < k; i++) {
            arr[scanner.nextInt()] = 1;
        }
        warr[0] = 1;
        winvarr[0] = 1;
        for (int i = 1; i < warr.length; i++) {
            warr[i] = warr[i - 1] * w % mod;
            winvarr[i] = winvarr[i - 1] * w % mod;
        }
        long[] fftArr = performFFT(arr);
        fftArr = raiseArrayToPower(fftArr, n / 2);
        Vector vector = new Vector(fftArr);
        long[] finalArr = vector.getInverseFFT();
        long sum = 0;
        for (long val : finalArr) {
            sum = (sum + val * val) % mod;
        }
        writer.println(sum);
    }

    public void run() {
        try {
            if (isConsoleIO) {
                scanner = new FastScanner(System.in);
                writer = new PrintWriter(System.out);
            } else {
                scanner = new FastScanner(new File("input.txt"));
                writer = new PrintWriter(new File("output.txt"));
            }
            process();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new FFT().run();
    }
}
